import type { Allowed } from '../lib/compare';
import { shellAllow } from './common-allow';

// What the live shell may draw differently from Sy-01 to Sy-08, each with the reason
// it is allowed. Every entry is one board, one element, one property and the two
// values as measured; an entry that stops matching fails the gate. An entry with
// `per` says the boards disagree and the console draws that other board's value: the
// gate measures that board too, and fails the entry unless it gives the live value.
// plan/00-foundation.md, "Deviations from the boards", says the same in words.

// ---------- the boards disagree; the console draws the topic's own boards ----------
// Sy-01 to Sy-03 draw a specimen topic page; Tp-05 (the topic and its messages) and
// Tp-06 (one message, opened) are the topic page's own boards, and where they differ
// the console is Tp-05's and Tp-06's.
const SPECIMEN = 'Sy-01, Sy-02 and Sy-05 pad their specimen page 14 18 0 with a 10 px gap and a 16 px title; Tp-05, Tp-06 and every section\'s page board pad it 16 20 0 with an 18 px title, as the console does on every page: what is in main is 2 px lower and further right, and 4 px narrower';
const TP05_LIST_HEAD = 'the list head is Tp-05\'s (and Tp-Home\'s): the count and + New over a rule, 45 px; Sy-01 draws a 36 px caption with no rule';
const LIST_UNDERLINE = 'the boards disagree: Tp-05 sets its list items\' text-decoration to none, Sy-01 and Sy-02 leave them to con.css\'s link underline; the console draws every list pane the one way, Tp-05\'s';
const TP05_TAB_COUNT = 'Tp-05 writes the count of partitions and of readers in their tabs ("Partitions 3"); Sy-01 and Sy-02 do not';
const TP05_VALUE = 'Tp-05 draws a record\'s value in ink (and Tp-06 tints it as JSON); Sy-01 and Sy-02 draw it muted';
const TP06_WIRE = 'with a message open the wire\'s columns are Tp-06\'s five (time 92, client 110, request 80, the detail the rest, result 40; the time it took is in the request\'s inspector); Sy-01 draws four (no client); Tp-05\'s six, which the console draws with nothing open, need 634 px and beside the inspector there are 576';
const DOCK3 = 'the wire is its head and three rows, 103 px with Tp-05\'s 24 px rows (Sy-01\'s rows are 28 px): it starts 12 px lower, above the keys strip';
const TP06_SUB = 'the line under the title names the topic in mono, as Tp-06 draws it; Sy-02 writes the time, the producer and the size there, in the page\'s face (the console has them in the fields below)';
const SY01_OVER_SY02 = 'Sy-01 and Sy-02 draw the same page and disagree; the console draws Sy-01\'s, the anatomy (its keys strip, its list foot note, its value track)';

// ---------- the console's structure ----------
const ONE_GRID = 'the wire is the page\'s own row under main, as on every page (one grid); the boards draw it inside main with negative margins, so their main runs to the keys strip';
const TABLE = 'the records are a <table>, so a screen reader walks them by row and column: a row is a table row, its fill, rule and header type are on its cells (anatomy.spec checks they are the board\'s), a cell is its row\'s 28 px, and the board\'s 14 px gaps are 7 px of padding each side of a cell (12 at the row\'s ends), so a cell starts 7 px before its text';
const TABLE_72 = 'as TABLE, and the offset track is 72 px, not 62, so 1,234,567 fits (the board\'s 62 holds 4,789; plan/00-foundation.md, Messages table): the offset cell is 86 px and the cells after it 10 px further right';
const HEAD_ROW = 'the inspector\'s head is a row: its text, and Tp-06\'s older, newer and close beside it (Sy-02 draws none); the 12 px is between those two, the cap is as wide as its word, and the text\'s lines are where Sy-02 draws them';
const VALUE_ROW = 'the value\'s caption shares its row with Tp-06\'s Text, Hex and Base64 switch (24 px), centred in it: 5 px lower than Sy-02\'s caption alone, as wide as its words, and the value 6 px lower';

const STACKED = 'at 960 the message is the inspector drawn as a card in its own row under main (the same panel at every width, so its keys and address are the same), not inside main: main ends above it, and the card\'s 16 px inset is its margin';
const BACK_PARTS = 'the arrow and the word are two parts (the word is "Topics" at 960 and "All topics" at 390), so the button\'s 6 px gap is none and the space between them is the text\'s own, as the board\'s one run of text';
const FIELD_NAMES = 'the boards disagree on the field names\' column (Sy-02 and Tp-06 84 px, Sy-03 70, Sy-04 64): the console draws one at every width, Sy-02\'s and Tp-06\'s';
const VALUE_COL = 'the value is in a column with its caption and Tp-06\'s Text, Hex and Base64 switch, which shares the card equally with the fields (416 px each); the board\'s code block, alone, takes its own 26 px of padding and border over its share';
const TP05_WIRE_960 = 'at 960 Tp-05\'s six columns fit (912 px) and the console draws them; Sy-03 draws four (no client, no took)';
const SR_WORDS = 'the button keeps its words, "Jump or act…", for a screen reader, clipped to nothing; the board names it with aria-label instead';
const DOT = 'the dot is inside the broker pill, whose address is read to a screen reader and not drawn, and the pill\'s type is 12 px; the board\'s dot sits in the top bar\'s 13 px; a dot has no text';
const TABS_SCROLL = 'the tabs scroll sideways in their own box, the screen\'s width less its margins (366); the board scrolls a wrapper the screen\'s width with the tabs 470 wide inside it: the same tabs and the same scroll';
const CARD_ROW = 'a card is the table\'s row laid out as a grid (the records are a table at every width): the key and its position share its first row 8 px apart (the board\'s row.sb), and the 8 px between cards is its margin, not the list\'s gap';
const SCRIM = 'the scrim is the sheet\'s own shadow, 100vmax of the board\'s scrim colour (narrow.spec checks the colour), not an element of its own';
const GRAB = 'the grab handle is the sheet\'s ::before, 36 x 4, centred, 8 px down, as the board\'s (narrow.spec checks it): the gate cannot select a pseudo-element';
const SHEET_PARTS = 'the sheet\'s head and body carry its 14 px and the 8 px between its parts themselves, so the record scrolls in the body under a head that stays; the board pads the sheet';
const TP06_ACTS = 'the actions are Tp-06\'s, Send again, Edit a copy… and Download value, beside Follow this trace (Copy as curl is CUT: plan/00-foundation.md), so they take two rows; they stay at the sheet\'s foot as the board\'s do, on the card\'s colour because the record scrolls under them';

// ---------- data: the seed is not the boards' sample ----------
const LIST_CAP = 'the caption is Tp-05\'s, "Topics · N · messages", with the seed\'s 14 topics; Sy-01 writes "Every topic" and Sy-02 "Topics"';
const SEED_ORDER = 'the open topic is seed-orders, the tenth of the seed\'s topics by name; the board\'s is its first';
const SEED_WARN = 'the board\'s second topic is a dead-letter topic holding records, coloured as needing a look; the seed\'s second (harbour-arrivals) needs none';
const NO_SCHEMA = 'the "matches schema" callout is drawn for a record written with a schema; Sy-02\'s record was, the seed\'s traced orders were not; anatomy.spec opens a seed-events record, written with one, and holds its callout';

// ---------- additions (plan/00-foundation.md, Additions to the design) ----------
